def calculate_expected_score(n, probabilities):
    from functools import lru_cache

    @lru_cache(None)
    def calculate_probability_of_sequence(n, probabilities):
        if n == 0:
            return 1.0
        prob = probabilities[n - 1]
        return prob * calculate_probability_of_sequence(n - 1, probabilities) + (1 - prob) * calculate_probability_of_sequence(n - 1, probabilities)

    @lru_cache(None)
    def calculate_score(sequence):
        score = 0
        count = 0
        for click in sequence:
            if click == 'O':
                count += 1
            else:
                if count > 0:
                    score += count ** 2
                    count = 0
        if count > 0:
            score += count ** 2
        return score

    total_score = 0.0
    for i in range(2 ** n):
        sequence = bin(i)[2:].zfill(n)
        total_score += calculate_probability_of_sequence(n, probabilities) * calculate_score(sequence)

    return total_score
