    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(n)]

    def calculate_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def calculate_polygon_perimeter(points):
        perimeter = 0
        for i in range(len(points)):
            perimeter += calculate_distance(points[i], points[(i + 1) % len(points)])
        return perimeter

    def is_valid_polygon(points):
        for i in range(len(points)):
            for j in range(i + 2, len(points)):
                for k in range(j + 2, len(points)):
                    if (points[j][0] - points[i][0]) * (points[k][1] - points[i][1]) == (points[k][0] - points[i][0]) * (points[j][1] - points[i][1]):
                        return False
        return True

    results = []
    for k in range(3, n + 1):
        max_perimeter = 0
        for i in range(n - k + 1):
            for j in range(i + k):
                for l in range(j + k):
                    if l == j:
                        continue
                    polygon = points[i:j] + points[l:]
                    if is_valid_polygon(polygon):
                        perimeter = calculate_polygon_perimeter(polygon)
                        if perimeter > max_perimeter:
                            max_perimeter = perimeter
        results.append(max_perimeter)

    for result in results:
        print(result)
